// pages/LoginPageView.tsx
import React from 'react';
import { LogIn, UserPlus, Mail } from 'react-feather';
import { Link } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { ReactComponent as AconectLogo } from '../assets/aconect-logo.svg';
import { ThemeSelector } from '../components/theme/ThemeSelector';
import LanguageSelector from '../components/language/LanguageSelector';
import './LoginPageView.scss';

interface LoginPageViewProps {
  email: string;
  onEmailChange: (email: string) => void;
  password: string;
  onPasswordChange: (password: string) => void;
  isLoading: boolean;
  error: string;
  isAutoLogging: boolean;
  onLogin: (e: React.FormEvent) => Promise<void>;
  onSignUp?: (e: React.FormEvent) => Promise<void>;
  onEmailOtp: (e: React.FormEvent) => Promise<void>;
  isOtpSent: boolean;
  otpCode: string;
  onOtpCodeChange: (code: string) => void;
  onVerifyOtp: (e: React.FormEvent) => Promise<void>;
  onResetOtp: () => void;
  usePassword: boolean;
  onUsePasswordChange: (use: boolean) => void;
}

/**
 * Pure UI component for the login page
 * This component is responsible only for rendering the UI
 * All business logic is handled by parent or hooks
 */
const LoginPageView: React.FC<LoginPageViewProps> = ({
  email,
  onEmailChange,
  password,
  onPasswordChange,
  isLoading,
  error,
  isAutoLogging,
  onLogin,
  onSignUp,
  onEmailOtp,
  isOtpSent,
  otpCode,
  onOtpCodeChange,
  onVerifyOtp,
  onResetOtp,
  usePassword,
  onUsePasswordChange,
}) => {
  const { t } = useTranslation();
  return (
    <div className="login-page-container">
      {/* Header Navigation */}
      <header className="login-header">
        <nav className="login-nav">
          <Link to="/" className="login-logo">
            <AconectLogo />
            <span>A-CONECT</span>
          </Link>
          <div className="login-nav-links">
            <Link to="/features" className="login-nav-link">
              {t('login.features')}
            </Link>
            <LanguageSelector />
            {/* <a href="#about" className="login-nav-link">
              About Us
            </a> */}
            <ThemeSelector />
          </div>
        </nav>
      </header>

      {/* Main Content Area */}
      <main className="login-main">
        {/* Background pattern */}
        <div className="login-bg-pattern"></div>

        <div className="login-content-wrapper">
          {/* Left Section - Tagline */}
          <div className="login-tagline-section">
            <h1 className="login-tagline-title">
              {t('login.taglineTitle')}
            </h1>
            <p className="login-tagline-subtitle">
              {t('login.taglineSubtitle')}
            </p>
          </div>

          {/* Right Section - Form */}
          <div className="login-form-section">
            {isAutoLogging ? (
              <AutoLoggingState />
            ) : isOtpSent ? (
              <OtpVerificationForm
                otpCode={otpCode}
                onOtpCodeChange={onOtpCodeChange}
                isLoading={isLoading}
                error={error}
                onVerifyOtp={onVerifyOtp}
                onBackClick={onResetOtp}
              />
            ) : (
              <LoginForm
                email={email}
                onEmailChange={onEmailChange}
                password={password}
                onPasswordChange={onPasswordChange}
                isLoading={isLoading}
                error={error}
                onLogin={onLogin}
                onEmailOtp={onEmailOtp}
                usePassword={usePassword}
                onUsePasswordChange={onUsePasswordChange}
              />
            )}
          </div>
        </div>
      </main>
    </div>
  );
};

/**
 * Auto-logging state component
 */
const AutoLoggingState: React.FC = () => {
  const { t } = useTranslation();
  return (
    <div className="login-form-card">
      <div className="login-auto-logging">
        <div className="login-auto-logging-title">
          {t('login.loggingInAutomatically')}
        </div>
        <div className="login-auto-logging-subtitle">
          {t('login.usingUrlCredentials')}
        </div>
      </div>
    </div>
  );
};

/**
 * Login form component
 */
interface LoginFormProps {
  email: string;
  onEmailChange: (email: string) => void;
  password: string;
  onPasswordChange: (password: string) => void;
  isLoading: boolean;
  error: string;
  onLogin: (e: React.FormEvent) => Promise<void>;
  onEmailOtp: (e: React.FormEvent) => Promise<void>;
  usePassword: boolean;
  onUsePasswordChange: (use: boolean) => void;
}

const LoginForm: React.FC<LoginFormProps> = ({
  email,
  onEmailChange,
  password,
  onPasswordChange,
  isLoading,
  error,
  onLogin,
  onEmailOtp,
  usePassword,
  onUsePasswordChange,
}) => {
  const { t } = useTranslation();
  return (
    <div className="login-form-card">
      <div className="login-form-header">
        <h2 className="login-form-title">{t('login.welcomeBack')}</h2>
      </div>

      <form className="login-form" onSubmit={usePassword ? onLogin : onEmailOtp}>
        {error && <ErrorAlert message={error} />}

        <EmailInput
          value={email}
          onChange={onEmailChange}
          disabled={isLoading}
        />

        {usePassword && (
          <PasswordInput
            value={password}
            onChange={onPasswordChange}
            disabled={isLoading}
          />
        )}

        <button
          type="submit"
          disabled={isLoading}
          className="login-submit-button"
        >
          {isLoading ? 
            (usePassword ? t('login.loggingIn') : t('login.sendingCode')) : 
            (usePassword ? t('login.loginButton') : t('login.sendCodeButton'))
          }
        </button>
      </form>

      {/* Password toggle section */}
      <div className="login-password-toggle-section">
        <button
          type="button"
          // className="login-password-toggle-button"
          className="login-social-button"
          onClick={() => onUsePasswordChange(!usePassword)}
          disabled={isLoading}
        >
          {usePassword ? t('login.useEmailButton') : t('login.usePasswordButton')}
        </button>
        {/* <button
          className="login-social-button"
          onClick={onEmailOtp}
          disabled={isLoading}
          type="button"
        >
          <Mail size={20} />
          {usePassword ? 'Use email login instead' : 'Log in via password'}
        </button> */}
      </div>

      {/* Divider */}
      {/* <div className="login-divider">
        <div className="login-divider-line"></div>
        <span className="login-divider-text">Or continue with</span>
        <div className="login-divider-line"></div>
      </div> */}

      {/* Email login button */}
      {/* <button 
        className="login-social-button"
        onClick={onEmailOtp}
        disabled={isLoading}
        type="button"
      >
        <Mail size={20} />
        Log in via email
      </button> */}

      {/* Divider */}
      <div className="login-divider">
        <div className="login-divider-line"></div>
        <span className="login-divider-text">{t('login.newToAConect')}</span>
        <div className="login-divider-line"></div>
      </div>

      {/* Join Waitlist button */}
      <button
        className="login-secondary-button"
        onClick={() => window.open('https://forms.gle/Nm77eKUpmUqDbPHe7', '_blank')}
      >
        {t('login.joinWaitlist')}
      </button>
    </div>
  );
};

/**
 * OTP verification form component
 */
interface OtpVerificationFormProps {
  otpCode: string;
  onOtpCodeChange: (code: string) => void;
  isLoading: boolean;
  error: string;
  onVerifyOtp: (e: React.FormEvent) => Promise<void>;
  onBackClick: () => void;
}

const OtpVerificationForm: React.FC<OtpVerificationFormProps> = ({
  otpCode,
  onOtpCodeChange,
  isLoading,
  error,
  onVerifyOtp,
  onBackClick,
}) => {
  const { t } = useTranslation();
  return (
    <div className="login-form-card">
      <div className="login-form-header">
        <h2 className="login-form-title">{t('login.verifyEmail')}</h2>
        <p className="login-form-subtitle">
          {t('login.verifyEmailSubtitle')}
        </p>
      </div>

      <form className="login-form" onSubmit={onVerifyOtp}>
        {error && <ErrorAlert message={error} />}

        <div className="login-input-group">
          <label className="login-input-label" htmlFor="otp">
            {t('login.verificationCodeLabel')}
          </label>
          <input
            id="otp"
            type="text"
            value={otpCode}
            onChange={(e) => onOtpCodeChange(e.target.value)}
            disabled={isLoading}
            className="login-input"
            placeholder={t('login.verificationCodePlaceholder') as string}
            maxLength={8}
            required
            autoFocus
          />
        </div>

        <button
          type="submit"
          disabled={isLoading}
          className="login-submit-button"
        >
          {isLoading ? t('login.verifying') : t('login.verifyButton')}
        </button>
      </form>

      <button
        className="login-secondary-button"
        onClick={onBackClick}
        disabled={isLoading}
        type="button"
      >
        {t('login.backButton')}
      </button>
    </div>
  );
};

/**
 * Error alert component
 */
interface ErrorAlertProps {
  message: string;
}

const ErrorAlert: React.FC<ErrorAlertProps> = ({ message }) => (
  <div className="login-error-alert">
    <span className="login-error-text">{message}</span>
  </div>
);

/**
 * Email input component
 */
interface EmailInputProps {
  value: string;
  onChange: (value: string) => void;
  disabled: boolean;
}

const EmailInput: React.FC<EmailInputProps> = ({
  value,
  onChange,
  disabled,
}) => {
  const { t } = useTranslation();
  return (
    <div className="login-input-group">
      <label className="login-input-label" htmlFor="email">
        {t('login.emailLabel')}
      </label>
      <input
        id="email"
        type="email"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        disabled={disabled}
        className="login-input"
        placeholder={t('login.emailPlaceholder') as string}
        required
        autoComplete="email"
      />
    </div>
  );
};

/**
 * Password input component
 */
interface PasswordInputProps {
  value: string;
  onChange: (value: string) => void;
  disabled: boolean;
}

const PasswordInput: React.FC<PasswordInputProps> = ({
  value,
  onChange,
  disabled,
}) => {
  const { t } = useTranslation();
  return (
    <div className="login-input-group">
      <label className="login-input-label" htmlFor="password">
        {t('login.passwordLabel')}
      </label>
      <input
        id="password"
        type="password"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        disabled={disabled}
        className="login-input"
        placeholder={t('login.passwordPlaceholder') as string}
        required
        autoComplete="current-password"
      />
    </div>
  );
};

export default LoginPageView;
