// pages/LoginPage.tsx
/**
 * LoginPage - Container component
 * 
 * Responsible for:
 * - Managing business logic (auth, API calls)
 * - Managing state
 * - Handling callbacks
 * 
 * Does NOT render UI directly - delegates to LoginPageView
 */
import React from 'react';
import LoginPageView from './LoginPageView';
import { useLoginLogic } from '../hooks/useLoginLogic';

interface LoginPageProps {
  onLogin?: (api_token: string) => void;
}

const LoginPage: React.FC<LoginPageProps> = ({ onLogin }) => {
  const [usePassword, setUsePassword] = React.useState(false);

  const {
    email,
    setEmail,
    password,
    setPassword,
    isLoading,
    error,
    isAutoLogging,
    handleLogin,
    handleSignUp,
    handleEmailOtp,
    isOtpSent,
    otpCode,
    setOtpCode,
    verifyOtpCode,
    resetOtpState,
  } = useLoginLogic({ onLogin });

  return (
    <LoginPageView
      email={email}
      onEmailChange={setEmail}
      password={password}
      onPasswordChange={setPassword}
      isLoading={isLoading}
      error={error}
      isAutoLogging={isAutoLogging}
      onLogin={handleLogin}
      onSignUp={handleSignUp}
      onEmailOtp={handleEmailOtp}
      isOtpSent={isOtpSent}
      otpCode={otpCode}
      onOtpCodeChange={setOtpCode}
      onVerifyOtp={verifyOtpCode}
      onResetOtp={resetOtpState}
      usePassword={usePassword}
      onUsePasswordChange={setUsePassword}
    />
  );
};

export default LoginPage;