import React, { useEffect } from 'react';
import { envConfig } from "../utils/env.config";
import Cookies from 'js-cookie';
import { Theme } from '../lib/themes';

function TopicImageView({ theme, topicIdList }: {
    theme: Theme;
    topicIdList: string[];
}) {
    // useEffect(() => {
    //     console.log('[TopicImageView] Received theme: ', theme);
    // }, [theme]);
    return (
        <>
            {topicIdList.map((topic, index) => (
                <div 
                    key={index} 
                    className="bg-white dark:bg-gray-900/50 border border-gray-200 dark:border-gray-800 rounded-lg p-4 cursor-default"
                >
                    <h2 className="text-center text-lg font-semibold mb-3 text-gray-900 dark:text-white capitalize">
                        {theme.topics[parseInt(topic) - 1].topic}
                    </h2>
                    <img
                        src={theme.topics[parseInt(topic) - 1].url}
                        alt={theme.topics[parseInt(topic) - 1].topic}
                        className="w-full h-auto object-cover rounded-md"
                    />
                </div>
            ))}
        </>
    );
}

export { TopicImageView };
