import axios from 'axios';
import { supabase } from './supabaseClient';

const apiService = {
    /**
     * Get a fresh session with valid access token, refreshing if necessary
     */
    getFreshSession: async () => {
        try {
            const { data: { session }, error: sessionError } = await supabase.auth.getSession();
            
            if (sessionError) {
                console.error('Failed to get session:', sessionError);
                return null;
            }
            
            if (!session?.access_token) {
                console.error('No active session or access token');
                return null;
            }
            
            // Check if token is expired or about to expire (within 1 minute)
            if (session.expires_at) {
                const expiresAt = session.expires_at * 1000; // Convert to milliseconds
                const now = Date.now();
                const timeUntilExpiry = expiresAt - now;
                
                if (timeUntilExpiry < 60000) { // Less than 1 minute
                    console.log('Token expiring soon, refreshing...');
                    const { data: { session: refreshedSession }, error: refreshError } = await supabase.auth.refreshSession();
                    
                    if (refreshError || !refreshedSession?.access_token) {
                        console.error('Failed to refresh session:', refreshError);
                        return null;
                    }
                    
                    return refreshedSession;
                }
            }
            
            return session;
        } catch (error) {
            console.error('Error getting fresh session:', error);
            return null;
        }
    },
    
    getOaiKey: async (): Promise<string | undefined> => {
        try {
            const session = await apiService.getFreshSession();
            if (!session?.access_token) {
                console.error('Failed to get valid session with access token');
                return undefined;
            }
            
            const response = await supabase.functions.invoke('get_oai_key', {
                headers: {
                    Authorization: `Bearer ${session.access_token}`
                }
            });
            
            if (response.error) {
                console.error(`Failed to get OAI key. Error: ${response.error.message}`);
                return undefined;
            }
            
            return response.data.secret;
        } catch (error) {
            console.error(`Failed to get OAI key. Error: ${error}`);
            return undefined;
        }
    },
    getRandomThemeImages: async (languageCode: string = 'en'): Promise<{ theme_id: string; topics: Array<{ id: number; topic: string; url: string }> } | undefined> => {
        try {
            const session = await apiService.getFreshSession();
            if (!session?.access_token) {
                console.error('Failed to get valid session with access token');
                return undefined;
            }
            
            const bucketName = `theme_images_${languageCode}`;
            console.log(`Fetching theme images from bucket: ${bucketName}`);
            const response = await supabase.functions.invoke('random_theme_images', {
                headers: {
                    Authorization: `Bearer ${session.access_token}`
                },
                body: {
                    bucket: bucketName
                }
            });
            
            if (response.error) {
                console.error(`Failed to get theme images. Error: ${response.error.message}`);
                return undefined;
            }
            
            return response.data;
            // Example response.data:
            // {
            //     theme_id: "001",
            //     topics: [
            //         { id: 1, topic: "aa", url: "https://..." },
            //         { id: 2, topic: "bb", url: "https://..." },
            //         { id: 3, topic: "cc", url: "https://..." }
            //     ]
            // }
        } catch (error) {
            console.error(`Failed to get theme images. Error: ${error}`);
            return undefined;
        }
    },
};

export default apiService;
