// hooks/useLoginLogic.ts
import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import apiService from '../lib/apiServer';

interface UseLoginLogicReturn {
  email: string;
  setEmail: (email: string) => void;
  password: string;
  setPassword: (password: string) => void;
  isLoading: boolean;
  error: string;
  isAutoLogging: boolean;
  handleLogin: (e: React.FormEvent) => Promise<void>;
  handleSignUp: (e: React.FormEvent) => Promise<void>;
  handleEmailOtp: (e: React.FormEvent) => Promise<void>;
  isOtpSent: boolean;
  otpCode: string;
  setOtpCode: (code: string) => void;
  verifyOtpCode: (e: React.FormEvent) => Promise<void>;
  resetOtpState: () => void;
}

interface UseLoginLogicProps {
  onLogin?: (api_token: string) => void;
}

export const useLoginLogic = ({ onLogin }: UseLoginLogicProps = {}): UseLoginLogicReturn => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [isAutoLogging, setIsAutoLogging] = useState(false);
  const [isOtpSent, setIsOtpSent] = useState(false);
  const [otpCode, setOtpCode] = useState('');
  const [otpEmail, setOtpEmail] = useState('');
  const { signIn, signInWithOtp, verifyOtp } = useAuth();
  const navigate = useNavigate();

  // Check for legacy password parameter in URL (backward compatibility)
  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const legacyPassword = urlParams.get('password');
    
    if (legacyPassword) {
      alert('Fail to handle password in param');
    }
  }, []);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    try {
      // First, authenticate with Supabase
      await signIn(email, password);
      
      // Then, get tokens from your custom API
      const oai_key = await apiService.getOaiKey();
      
      if (oai_key != undefined) {
        onLogin?.(email);  // FIXME: pass email as token for now
        navigate('/chat');
      } else {
        setError('Failed to load user data. Please contact support.');
      }
    } catch (err: any) {
      // alert('Login failed. Please try again.');
      console.error('Login error:', err);
      setError(err.message || 'Invalid email or password. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleSignUp = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    if (password.length < 6) {
      setError('Password must be at least 6 characters long.');
      setIsLoading(false);
      return;
    }

    try {
      // This will need to be implemented based on your requirements
      // For now, we'll show a message
      setError('Sign up is currently disabled. Please contact the administrator.');
    } catch (err: any) {
      console.error('Sign up error:', err);
      setError(err.message || 'An error occurred during sign up. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleEmailOtp = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    if (!email) {
      setError('Please enter your email address.');
      setIsLoading(false);
      return;
    }

    try {
      await signInWithOtp(email);
      setOtpEmail(email);
      setIsOtpSent(true);
      setError('');
    } catch (err: any) {
      console.error('Email OTP error:', err);
      if (err.message.includes('Signups not allowed for otp')) {
        setError('The email has not been signed up.');
      } else {
        setError(err.message || 'Failed to send verification code. Please try again.');
      }
      setIsOtpSent(false);
    } finally {
      setIsLoading(false);
    }
  };

  const verifyOtpCode = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    if (!otpCode) {
      setError('Please enter the verification code.');
      setIsLoading(false);
      return;
    }

    try {
      await verifyOtp(otpEmail, otpCode);
      
      // Then, get tokens from your custom API
      const oai_key = await apiService.getOaiKey();
      
      if (oai_key != undefined) {
        onLogin?.(otpEmail);
        navigate('/chat');
      } else {
        setError('Failed to load user data. Please contact support.');
      }
    } catch (err: any) {
      console.error('OTP verification error:', err);
      setError(err.message || 'Invalid verification code. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const resetOtpState = () => {
    setIsOtpSent(false);
    setOtpCode('');
    setOtpEmail('');
    setError('');
  };

  return {
    email,
    setEmail,
    password,
    setPassword,
    isLoading,
    error,
    isAutoLogging,
    handleLogin,
    handleSignUp,
    handleEmailOtp,
    isOtpSent,
    otpCode,
    setOtpCode,
    verifyOtpCode,
    resetOtpState,
  };
};
