import React from 'react';
import { Link } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { X, LogOut, Zap, Menu } from 'react-feather';
import { ReactComponent as AconectLogo } from '../assets/aconect-logo.svg';

import { Button } from '../components/button/Button';
import { Toggle } from '../components/toggle/Toggle';
import { TopicImageView } from '../components/TopicImageView';
import { ConfirmModal } from '../components/modal/Modal';
import LanguageSelector from '../components/language/LanguageSelector';
import { ThemeSelector } from '../components/theme/ThemeSelector';

import { Theme } from '../lib/themes';
import { ItemType } from '@openai/realtime-api-beta/dist/lib/client.js';
import { APP_VERSION } from '../config/version';

import './ConsolePage.scss';

interface ConsolePageViewProps {
  // State
  items: ItemType[];
  isConnected: boolean;
  canPushToTalk: boolean;
  isRecording: boolean;
  memoryKv: { [key: string]: any };
  topicIdList: string[];
  showConversation: boolean;
  currentDuration: string;
  showFeedbackModal: boolean;
  showDataSharingModal: boolean;
  showNewConversationModal: boolean;
  isDebugMode: boolean;
  botName: string;

  // Refs
  clientCanvasRef: React.RefObject<HTMLCanvasElement>;
  serverCanvasRef: React.RefObject<HTMLCanvasElement>;
  eventsScrollRef: React.RefObject<HTMLDivElement>;

  // Callbacks
  onConnect: () => void;
  onDisconnect: () => void;
  onStartRecording: () => void;
  onStopRecording: () => void;
  onChangeTurnEndType: (value: string) => void;
  onDeleteConversationItem: (id: string) => void;
  onLogout: () => void;
  onDownloadConversation: () => void;
  onShowConversationToggle: (value: boolean) => void;
  onFeedbackConfirm: () => void;
  onFeedbackDecline: () => void;
  onDataSharingConfirm: () => void;
  onDataSharingDecline: () => void;
  onNewConversationConfirm: () => void;
  onNewConversationDecline: () => void;
  onLanguageChange?: (langCode: string) => void;

  // Theme
  theme: Theme;
}

/**
 * ConsolePageView - Pure presentation component
 * Handles all UI rendering logic without business logic
 */
export const ConsolePageView: React.FC<ConsolePageViewProps> = ({
  items,
  isConnected,
  canPushToTalk,
  isRecording,
  memoryKv,
  topicIdList,
  showConversation,
  currentDuration,
  showFeedbackModal,
  showDataSharingModal,
  showNewConversationModal,
  isDebugMode,
  botName,
  clientCanvasRef,
  serverCanvasRef,
  eventsScrollRef,
  onConnect,
  onDisconnect,
  onStartRecording,
  onStopRecording,
  onChangeTurnEndType,
  onDeleteConversationItem,
  onLogout,
  onDownloadConversation,
  onShowConversationToggle,
  onFeedbackConfirm,
  onFeedbackDecline,
  onDataSharingConfirm,
  onDataSharingDecline,
  onNewConversationConfirm,
  onNewConversationDecline,
  onLanguageChange,
  theme,
}) => {
  const { t, i18n } = useTranslation();
  const currentLanguage = i18n.language.split('-')[0]; // Get language code (e.g., 'en', 'ja', 'zh')
  const avatarSrc = `/bot-avatar/${currentLanguage}.png`;
  const [mobileMenuOpen, setMobileMenuOpen] = React.useState(false);

  return (
    <div data-component="ConsolePage" className="flex flex-col min-h-screen bg-background-light dark:bg-background-dark">
      {/* Sticky Header */}
      <header className="login-header">

        {/* Desktop Navigation */}
        <nav className="login-nav">
          <Link to="/" className="login-logo">
            <AconectLogo />
            <span>A-CONECT
              <span className="hidden sm:inline text-xs font-light text-gray-500 dark:text-gray-400">(v{APP_VERSION})</span>
            </span>
          </Link>
          {/* Mobile Menu Button */}
          <button
            className="md:hidden flex items-center justify-center p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 text-gray-900 dark:text-white"
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
          >
            <Menu size={24} />
          </button>
          <div className="hidden md:flex items-center gap-6 text-sm">
          {/* <a
            href="project"
            className="text-gray-900 dark:text-white hover:text-primary dark:hover:text-white transition-colors"
          >
            {t('common.research')}
          </a> */}
          <a
            href="https://forms.gle/aL879bVUwJUEgfpx6"
            className="text-gray-900 dark:text-white hover:text-primary dark:hover:text-white transition-colors"
          >
            {t('common.feedback')}
          </a>
          {/* <Link
            to="/privacy"
            className="text-gray-900 dark:text-white hover:text-primary dark:hover:text-white transition-colors"
          >
            {t('common.privacy')}
          </Link> */}
          <div className="relative">
            <LanguageSelector onLanguageChange={onLanguageChange} />
          </div>
          <ThemeSelector />
          <a
            onClick={onLogout}
            className="flex items-center gap-2 text-gray-900 dark:text-white hover:text-primary dark:hover:text-white transition-colors cursor-pointer"
          >
            <span>{t('common.logout')}</span>
            <LogOut size={20} />
          </a>
          </div>
        </nav>

      </header>

      {/* Mobile Menu */}
      {mobileMenuOpen && (
        <div className="md:hidden fixed top-16 left-0 right-0 z-30 bg-background-light dark:bg-background-dark border-b border-gray-200 dark:border-gray-800 px-6 py-4 shadow-lg max-h-screen overflow-y-auto">
          <nav className="flex flex-col gap-4 text-sm">
            {/* <a href="project" className="text-gray-900 dark:text-white hover:text-primary dark:hover:text-white transition-colors">
              {t('common.research')}
            </a> */}
            <a href="https://forms.gle/aL879bVUwJUEgfpx6" className="text-gray-900 dark:text-white hover:text-primary dark:hover:text-white transition-colors">
              {t('common.feedback')}
            </a>
            {/* <Link to="/privacy" className="text-gray-900 dark:text-white hover:text-primary dark:hover:text-white transition-colors">
              {t('common.privacy')}
            </Link> */}
            <LanguageSelector onLanguageChange={onLanguageChange} />
            <ThemeSelector />
            <a
              onClick={() => {
                setMobileMenuOpen(false);
                onLogout();
              }}
              className="flex items-center gap-2 text-gray-900 dark:text-white hover:text-primary dark:hover:text-white transition-colors cursor-pointer"
            >
              <span>{t('common.logout')}</span>
              <LogOut size={20} />
            </a>
          </nav>
        </div>
      )}

      {/* Main Content */}
      <main className="flex-grow flex flex-col lg:flex-row gap-10 py-8 lg:pb-8 pb-32 px-6 sm:px-8 md:px-10">
        {/* Left Panel - Topic Grid and Visualization */}
        <div className="w-full">
          {/* Topic Cards Grid */}
          <div
            className={`topic-image-container grid gap-8 ${
              topicIdList.length === 1
                ? 'grid-cols-1 max-w-full'
                : 'grid-cols-1 md:grid-cols-2 xl:grid-cols-3'
            }`}
            style={{ maxWidth: '100%', height: 'auto' }}
          >
            <TopicImageView theme={theme} topicIdList={topicIdList} />
          </div>
        </div>
      </main>

      {/* Footer with Controls and Visualization */}
      <footer className="pt-6 border-t border-gray-200 dark:border-gray-800 px-6 sm:px-8 md:px-10 pb-6">
        <div className="flex justify-between items-center gap-4">
          {/* Save Conversation Button */}
          <button
            onClick={onDownloadConversation}
            className="bg-gray-100 dark:bg-gray-800 text-gray-800 dark:text-gray-200 font-medium py-2.5 px-6 rounded-full hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors"
          >
            {t('common.saveConversation') || 'Save Conv'}
          </button>

          {/* VAD Toggle (Debug Mode Only) */}
          {isDebugMode && (
            <Toggle
              defaultValue={true}
              labels={['manual', 'vad']}
              values={['none', 'server_vad']}
              onChange={(_, value) => onChangeTurnEndType(value)}
            />
          )}
        </div>
      </footer>

      {/* Fixed Avatar and Controls - Bottom Right */}
      <div className="fixed bottom-6 right-6 z-30 flex flex-col items-center gap-3">
        {/* Avatar Circle with Audio Visualization on Top */}
        <div className="flex flex-col items-center gap-2">
          <div className="relative w-28 h-28 lg:w-36 lg:h-36">
            <div className="absolute inset-0 rounded-full bg-gradient-to-b from-gray-100 to-gray-200 dark:from-gray-700 dark:to-gray-800 transform scale-105"></div>
            <img
              src={avatarSrc}
              alt={botName}
              className="relative w-full h-full object-cover rounded-full shadow-lg"
            />
            
            {/* Audio Visualization - Positioned on Bottom */}
            <div className="visualization absolute -bottom-3 left-0 right-0 flex items-center justify-center gap-1">
              <canvas
                ref={clientCanvasRef}
                className="visualization-entry client flex-grow h-1 max-w-16"
              // style={{ background: 'linear-gradient(to right, rgb(100, 150, 200), transparent)' }}
              />
              <canvas
                ref={serverCanvasRef}
                className="visualization-entry server flex-grow h-1 max-w-16"
              // style={{ background: 'linear-gradient(to right, rgb(100, 200, 100), transparent)' }}
              />
            </div>
          </div>
          
          {/* Bot Name - Below Avatar */}
          <p className="text-sm font-semibold text-gray-900 dark:text-white text-center">
            {botName}
          </p>
        </div>

        {/* Duration Display */}
        <p className="text-base font-medium text-gray-900 dark:text-white bg-background-light/50 dark:bg-background-dark/50 backdrop-blur-sm px-3 py-1 rounded-full shadow">
          {currentDuration || '00:00'}
        </p>

        {/* Connect/Disconnect Button */}
        <button
          onClick={isConnected ? onDisconnect : onConnect}
          className={`font-semibold py-3 px-6 rounded-full flex items-center gap-2 transition-transform hover:scale-105 shadow-lg ${
            isConnected
              ? 'bg-gray-100 dark:bg-gray-800 text-gray-800 dark:text-gray-200 hover:bg-gray-200 dark:hover:bg-gray-700'
              : 'bg-primary text-white hover:bg-opacity-90'
          }`}
        >
          {isConnected ? (
            <>
              <X size={20} />
              {t('common.end') || 'End'}
            </>
          ) : (
            <>
              <Zap size={20} />
              {t('common.start') || 'Start'}
            </>
          )}
        </button>

        {/* Push to Talk Button (when connected) */}
        {isConnected && canPushToTalk && (
          <button
            onMouseDown={onStartRecording}
            onMouseUp={onStopRecording}
            className={`font-semibold py-2 px-4 rounded-full text-sm transition-all ${
              isRecording
                ? 'bg-red-500 text-white hover:bg-red-600'
                : 'bg-blue-500 text-white hover:bg-blue-600'
            } shadow-lg`}
          >
            {isRecording ? t('common.releaseToSend') || 'Release' : t('common.pushToTalk') || 'PTT'}
          </button>
        )}
      </div>

      {/* Debug Console - Conversation Log (Hidden by default, toggle in top-left) */}
      {isDebugMode && (
        <>
          <div
            className="fixed bottom-80 right-6 z-20 bg-background-light dark:bg-background-dark border border-gray-200 dark:border-gray-800 rounded-lg p-4 max-w-md max-h-80 overflow-auto cursor-pointer"
            onClick={() => onShowConversationToggle(!showConversation)}
            style={{
              display: showConversation ? 'block' : 'none',
            }}
          >
            <div className="font-bold mb-2">Conversation Log {showConversation ? '▼' : '▶'}</div>
            <div className="text-sm space-y-2">
              {!items.length && <div>Awaiting connection...</div>}
              {items.map((conversationItem) => (
                <div key={conversationItem.id} className="border-b border-gray-200 dark:border-gray-700 pb-2">
                  <div className="flex justify-between items-start">
                    <span className="font-semibold text-xs">
                      {(conversationItem.role || conversationItem.type).replaceAll('_', ' ')}
                    </span>
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        onDeleteConversationItem(conversationItem.id);
                      }}
                      className="text-red-500 hover:text-red-700"
                    >
                      <X size={14} />
                    </button>
                  </div>
                  <div className="text-xs text-gray-600 dark:text-gray-400 mt-1">
                    {conversationItem.type === 'function_call_output' && (
                      <div>{conversationItem.formatted.output || ''}</div>
                    )}
                    {!!conversationItem.formatted.tool && (
                      <div>
                        {conversationItem.formatted.tool.name}(
                        {conversationItem.formatted.tool.arguments})
                      </div>
                    )}
                    {!conversationItem.formatted.tool && conversationItem.role === 'user' && (
                      <div>
                        {conversationItem.formatted.transcript ||
                          (conversationItem.formatted.audio?.length
                            ? '(awaiting transcript)'
                            : conversationItem.formatted.text || '(item sent)')}
                      </div>
                    )}
                    {!conversationItem.formatted.tool && conversationItem.role === 'assistant' && (
                      <div>
                        {conversationItem.formatted.transcript ||
                          conversationItem.formatted.text ||
                          '(truncated)'}
                      </div>
                    )}
                  </div>
                </div>
              ))}
            </div>

            {/* Memory Display */}
            <div className="mt-4 pt-4 border-t border-gray-200 dark:border-gray-700">
              <div className="font-semibold text-xs mb-2">{botName}'s Memory</div>
              <pre className="text-xs bg-gray-100 dark:bg-gray-800 p-2 rounded overflow-auto max-h-40">
                {JSON.stringify(memoryKv, null, 2)}
              </pre>
            </div>
          </div>
        </>
      )}

      {/* Modals */}
      <ConfirmModal
        isOpen={showFeedbackModal}
        onClose={onFeedbackDecline}
        onConfirm={onFeedbackConfirm}
        title="Feedback Request"
        message="Thank you for using A-CONECT! Would you like to provide feedback to help us improve? This will open a survey form in a new tab."
        confirmText="Yes, provide feedback"
        cancelText="Skip"
      />

      <ConfirmModal
        isOpen={showNewConversationModal}
        onClose={onNewConversationDecline}
        onConfirm={onNewConversationConfirm}
        title="Start New Conversation"
        message="Would you like to refresh the page to start a new conversation? This will clear your current session and begin fresh."
        confirmText="Yes, start new conversation"
        cancelText="No, stay here"
      />
    </div>
  );
};
