import React, { useCallback } from 'react';
import { Theme } from '../lib/themes';
import { useConsolePage } from '../hooks/useConsolePage';
import { ConsolePageView } from './ConsolePageView';

interface ConsolePageProps {
  onLogout: () => void;
  apiKey: string;
  theme: Theme;
}

/**
 * ConsolePage - Container component
 * Manages all logic through custom hooks and passes data to presentation component
 * This keeps the component focused on orchestration rather than implementation
 */
const ConsolePage: React.FC<ConsolePageProps> = ({ onLogout, apiKey, theme }) => {
  // Use custom hook for all business logic
  const {
    // State
    items,
    realtimeEvents,
    expandedEvents,
    isConnected,
    canPushToTalk,
    isRecording,
    memoryKv,
    topicIdList,
    showConversation,
    currentDuration,
    showFeedbackModal,
    showDataSharingModal,
    showNewConversationModal,
    isDebugMode,
    botName,

    // Refs
    clientCanvasRef,
    serverCanvasRef,
    eventsScrollRef,

    // Callbacks
    connectConversation,
    disconnectConversation,
    cleanupAllResources,
    startRecording,
    stopRecording,
    changeTurnEndType,
    deleteConversationItem,
    resetAPIKey,
    formatTime,
    handleFeedbackConfirm,
    handleFeedbackDecline,
    handleDataSharingConfirm,
    handleDataSharingDecline,
    handleNewConversationConfirm,
    handleNewConversationDecline,
    downloadConversation,

    // Setters
    setShowConversation,
    setShowFeedbackModal,
    setShowDataSharingModal,
    setShowNewConversationModal,
  } = useConsolePage(apiKey, theme);

  /**
   * Handle logout - cleanup resources then call parent logout handler
   */
  const handleLogout = useCallback(async () => {
    await cleanupAllResources();
    onLogout();
  }, [cleanupAllResources, onLogout]);

  /**
   * Handle language change - reload the page to update all settings
   */
  const handleLanguageChange = useCallback(async (langCode: string) => {
    // Disconnect conversation and cleanup before reloading
    await cleanupAllResources();
    // Reload the page to refresh all language-dependent settings
    window.location.reload();
  }, [cleanupAllResources]);


  /**
   * Render the application using the presentation component
   */
  return (
    <ConsolePageView
      // State props
      items={items}
      isConnected={isConnected}
      canPushToTalk={canPushToTalk}
      isRecording={isRecording}
      memoryKv={memoryKv}
      topicIdList={topicIdList}
      showConversation={showConversation}
      currentDuration={currentDuration}
      showFeedbackModal={showFeedbackModal}
      showDataSharingModal={showDataSharingModal}
      showNewConversationModal={showNewConversationModal}
      isDebugMode={isDebugMode}
      botName={botName}
      // Refs
      clientCanvasRef={clientCanvasRef}
      serverCanvasRef={serverCanvasRef}
      eventsScrollRef={eventsScrollRef}
      // Callbacks
      onConnect={connectConversation}
      onDisconnect={disconnectConversation}
      onStartRecording={startRecording}
      onStopRecording={stopRecording}
      onChangeTurnEndType={changeTurnEndType}
      onDeleteConversationItem={deleteConversationItem}
      onLogout={handleLogout}
      onDownloadConversation={downloadConversation}
      onShowConversationToggle={setShowConversation}
      onFeedbackConfirm={handleFeedbackConfirm}
      onFeedbackDecline={handleFeedbackDecline}
      onDataSharingConfirm={handleDataSharingConfirm}
      onDataSharingDecline={handleDataSharingDecline}
      onNewConversationConfirm={handleNewConversationConfirm}
      onNewConversationDecline={handleNewConversationDecline}
      onLanguageChange={handleLanguageChange}
      // Theme
      theme={theme}
    />
  );
};

export default ConsolePage;
