/**
 * Utility functions for cleaning up legacy localStorage and cookies
 */

import {
  APP_VERSION,
  VERSION_COOKIE_NAME,
  VERSION_COOKIE_EXPIRATION_DAYS,
} from '../config/version';

// Keys to preserve when cleaning localStorage
const STORAGE_KEYS_TO_PRESERVE = ['i18nextLng', 'theme-preference'];

// Cookies to preserve when cleaning
const COOKIE_KEYS_TO_PRESERVE = [VERSION_COOKIE_NAME];

/**
 * Clear all cookies from the browser except specified ones
 */
export const clearAllCookies = (): void => {
  document.cookie.split(';').forEach((cookie) => {
    const eqPos = cookie.indexOf('=');
    const name = eqPos > -1 ? cookie.substring(0, eqPos).trim() : cookie.trim();
    
    // Skip preserving cookies
    if (COOKIE_KEYS_TO_PRESERVE.includes(name)) {
      return;
    }
    
    document.cookie = `${name}=;expires=Thu, 01 Jan 1970 00:00:00 UTC;path=/`;
  });
};

/**
 * Clear all localStorage except specified keys
 * When user is not authenticated, this removes legacy data while preserving essential preferences
 */
export const clearLegacyLocalStorage = (): void => {
  const keysToRemove: string[] = [];

  // Identify all keys that should be removed
  for (let i = 0; i < localStorage.length; i++) {
    const key = localStorage.key(i);
    if (key && !STORAGE_KEYS_TO_PRESERVE.includes(key)) {
      keysToRemove.push(key);
    }
  }

  // Remove identified keys
  keysToRemove.forEach((key) => {
    localStorage.removeItem(key);
  });

  if (keysToRemove.length > 0) {
    console.log(
      `Cleared legacy localStorage. Removed keys: ${keysToRemove.join(', ')}. Preserved keys: ${STORAGE_KEYS_TO_PRESERVE.join(', ')}`
    );
  }
};

/**
 * Perform complete cleanup of legacy data for unauthenticated users
 */
export const cleanupLegacyData = (): void => {
  clearAllCookies();
  clearLegacyLocalStorage();
};

/**
 * Get the version ID from cookie
 */
export const getVersionFromCookie = (): string | null => {
  const name = `${VERSION_COOKIE_NAME}=`;
  const decodedCookie = decodeURIComponent(document.cookie);
  const cookieArray = decodedCookie.split(';');

  for (let cookie of cookieArray) {
    cookie = cookie.trim();
    if (cookie.indexOf(name) === 0) {
      return cookie.substring(name.length, cookie.length);
    }
  }

  return null;
};

/**
 * Set the version ID in cookie with expiration
 */
export const setVersionInCookie = (): void => {
  const path = 'path=/';
  const sameSite = 'SameSite=Lax';

  document.cookie = `${VERSION_COOKIE_NAME}=${APP_VERSION};${path};${sameSite}`;

  // console.log(`Version ID set in cookie: ${APP_VERSION}`);
};

/**
 * Check if the app version has changed
 * Returns true if version has changed or no version cookie exists
 */
export const hasVersionChanged = (): boolean => {
  const storedVersion = getVersionFromCookie();

  if (storedVersion === null) {
    console.log('No version cookie found. First time or cookies cleared.');
    return true;
  }

  if (storedVersion !== APP_VERSION) {
    console.log(
      `Version mismatch detected. Stored: ${storedVersion}, Current: ${APP_VERSION}`
    );
    return true;
  }

  // console.log(`Version is up to date: ${APP_VERSION}`);
  return false;
};
